(() => {
  'use strict';
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const mapCanvas = document.getElementById('mapCanvas');
  const mapCtx = mapCanvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const $$ = (s) => [...document.querySelectorAll(s)];
  const rand = (a,b) => a + Math.random()*(b-a);
  const clamp = (n,a,b) => Math.max(a,Math.min(b,n));
  const game = {
    started:false, zone:'wilds', player:{x:22,y:63,hp:184,maxHp:220,mana:96,maxMana:120,xp:2460,gold:1240,potions:2,dir:1,attack:0,walk:0,level:12},
    quest:{riftFound:false,riftDone:false,essence:false}, keys:{}, pointer:null, toastTimer:null,
    hound:{x:52,y:57,hp:100,maxHp:100,alive:true,aggro:false,attackCd:0},
    rift:{x:78,y:36}, maria:{x:29,y:49}, rocky:{x:33,y:50}, enemies:[], drops:[], loot:[], chatNpc:'Maria', chatTurns:0, time:0,
    cooldowns:[0,0,0], scene:'wilds', ambientIndex:0
  };
  const ambientLines=['The wind carries a distant howl.','Ash drifts down from a cloudless sky.','Something watches from the tree line.','The veil trembles, just beyond sight.'];
  const mapProps=[];
  let seed=812;
  function sr(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
  for(let i=0;i<100;i++){mapProps.push({x:sr()*100,y:sr()*100,type:sr()<.8?'tree':'rock',size:5+sr()*11,variant:sr()})}
  function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);draw()}
  function point(x,y,w,h){const scale=Math.min(w/75,h/73);return {x:w/2+(x-game.player.x)*scale,y:h*.56+(y-game.player.y)*scale,s:scale}}
  function ground(w,h){
    const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#1b2526');sky.addColorStop(.4,'#29312b');sky.addColorStop(1,'#34372d');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
    // hazy mountain silhouettes
    ctx.fillStyle='#182224';ctx.beginPath();ctx.moveTo(0,h*.32);for(let x=0;x<=w+30;x+=30)ctx.lineTo(x,h*.24+Math.sin(x*.021)*14+Math.cos(x*.037)*8);ctx.lineTo(w,h*.55);ctx.lineTo(0,h*.55);ctx.fill();
    ctx.fillStyle='#252d27';ctx.beginPath();ctx.moveTo(0,h*.43);for(let x=0;x<=w+20;x+=20)ctx.lineTo(x,h*.34+Math.sin(x*.018+2)*12+Math.cos(x*.045)*5);ctx.lineTo(w,h*.62);ctx.lineTo(0,h*.62);ctx.fill();
    // forest floor
    ctx.fillStyle='#35372d';ctx.fillRect(0,h*.43,w,h*.57);
    for(let i=0;i<80;i++){let x=(i*83+11)%w,y=h*.44+((i*137)%Math.max(1,h*.55));ctx.fillStyle=i%3?'#51503a55':'#88805726';ctx.fillRect(x,y,rand(1,3),rand(1,2));}
    // winding worn trail toward the rift
    ctx.beginPath();ctx.moveTo(w*.65,h*1.1);ctx.bezierCurveTo(w*.72,h*.83,w*.45,h*.74,w*.57,h*.58);ctx.bezierCurveTo(w*.74,h*.39,w*.56,h*.31,w*.70,h*.03);ctx.lineWidth=Math.max(26,w*.075);ctx.strokeStyle='#514b3c';ctx.stroke();ctx.lineWidth=Math.max(17,w*.05);ctx.strokeStyle='#69604b';ctx.stroke();
    ctx.beginPath();ctx.moveTo(w*.65,h*1.1);ctx.bezierCurveTo(w*.72,h*.83,w*.45,h*.74,w*.57,h*.58);ctx.bezierCurveTo(w*.74,h*.39,w*.56,h*.31,w*.70,h*.03);ctx.lineWidth=1;ctx.strokeStyle='#a1926c33';ctx.setLineDash([3,8]);ctx.stroke();ctx.setLineDash([]);
  }
  function tree(x,y,size,variant){
    const p=point(x,y,canvas.clientWidth,canvas.clientHeight),s=p.s,xx=p.x,yy=p.y,scale=clamp(s/9,.45,1.8),z=size*scale;
    if(xx<-50||xx>canvas.clientWidth+50||yy<-100||yy>canvas.clientHeight+30)return;
    ctx.fillStyle='#11161466';ctx.beginPath();ctx.ellipse(xx,yy+z*.2,z*.9,z*.28,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#302a20';ctx.fillRect(xx-z*.13,yy-z*.55,z*.26,z*.65);
    const colors=variant<.33?['#192a26','#263a30','#364333']:variant<.66?['#1b2725','#26312c','#414235']:['#1a2926','#2c3930','#424735'];
    for(let j=0;j<3;j++){ctx.beginPath();ctx.moveTo(xx,yy-z*(1.9-j*.42));ctx.lineTo(xx-z*(.8-j*.16),yy-z*(.45-j*.05));ctx.lineTo(xx+z*(.8-j*.16),yy-z*(.45-j*.05));ctx.closePath();ctx.fillStyle=colors[j];ctx.fill();}
    ctx.strokeStyle='#a58c5633';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(xx,yy-z*1.35);ctx.lineTo(xx,yy-z*.45);ctx.stroke();
  }
  function rock(x,y,size){const p=point(x,y,canvas.clientWidth,canvas.clientHeight),z=size*clamp(p.s/9,.45,1.6);if(p.x<-30||p.x>canvas.clientWidth+30||p.y<-30||p.y>canvas.clientHeight+30)return;ctx.fillStyle='#17191877';ctx.beginPath();ctx.ellipse(p.x,p.y+z*.2,z*.9,z*.3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#55574d';ctx.beginPath();ctx.moveTo(p.x-z,p.y);ctx.lineTo(p.x-z*.52,p.y-z*.64);ctx.lineTo(p.x+z*.2,p.y-z*.82);ctx.lineTo(p.x+z,p.y-z*.2);ctx.lineTo(p.x+z*.65,p.y+z*.17);ctx.closePath();ctx.fill();ctx.fillStyle='#858371';ctx.beginPath();ctx.moveTo(p.x-z*.52,p.y-z*.64);ctx.lineTo(p.x+z*.2,p.y-z*.82);ctx.lineTo(p.x+z*.45,p.y-z*.19);ctx.lineTo(p.x-z*.34,p.y-z*.19);ctx.closePath();ctx.fill()}
  function drawPerson(x,y,kind,scale=1){const p=point(x,y,canvas.clientWidth,canvas.clientHeight),z=clamp(p.s/9,.6,1.45)*scale,xx=p.x,yy=p.y;if(xx<-40||xx>canvas.clientWidth+40||yy<-50||yy>canvas.clientHeight+30)return;
    ctx.fillStyle='#11131288';ctx.beginPath();ctx.ellipse(xx,yy+3*z,11*z,4*z,0,0,Math.PI*2);ctx.fill();
    if(kind==='player'){
      // coat and hooded silhouette
      ctx.fillStyle='#14171a';ctx.beginPath();ctx.moveTo(xx-7*z,yy-5*z);ctx.lineTo(xx-10*z,yy+9*z);ctx.lineTo(xx+10*z,yy+9*z);ctx.lineTo(xx+7*z,yy-5*z);ctx.closePath();ctx.fill();
      ctx.fillStyle='#353638';ctx.beginPath();ctx.moveTo(xx-7*z,yy-5*z);ctx.lineTo(xx,yy-12*z);ctx.lineTo(xx+7*z,yy-5*z);ctx.lineTo(xx+5*z,yy+5*z);ctx.lineTo(xx-5*z,yy+5*z);ctx.closePath();ctx.fill();
      ctx.fillStyle='#c1a47a';ctx.beginPath();ctx.arc(xx,yy-11*z,4*z,0,Math.PI*2);ctx.fill();ctx.fillStyle='#211d1a';ctx.beginPath();ctx.arc(xx,yy-13*z,4.5*z,Math.PI,Math.PI*2);ctx.fill();
      ctx.strokeStyle='#a63f42';ctx.lineWidth=2*z;ctx.beginPath();ctx.moveTo(xx+4*z,yy+1*z);ctx.lineTo(xx+12*z,yy-8*z);ctx.stroke();ctx.fillStyle='#d3b77b';ctx.fillRect(xx+10*z,yy-10*z,3*z,3*z);
      if(game.player.attack>0){ctx.strokeStyle='#dcdbc4';ctx.lineWidth=2*z;ctx.beginPath();ctx.arc(xx,yy,17*z,-1.2,.7);ctx.stroke()}
      if(game.player.walk>0){ctx.strokeStyle='#d0b679';ctx.globalAlpha=.5;ctx.beginPath();ctx.arc(xx,yy,18*z,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
    }else if(kind==='maria'){
      ctx.fillStyle='#4b4d3e';ctx.beginPath();ctx.moveTo(xx-7*z,yy-4*z);ctx.lineTo(xx-10*z,yy+9*z);ctx.lineTo(xx+10*z,yy+9*z);ctx.lineTo(xx+7*z,yy-4*z);ctx.closePath();ctx.fill();ctx.fillStyle='#c2a277';ctx.beginPath();ctx.arc(xx,yy-10*z,4*z,0,Math.PI*2);ctx.fill();ctx.fillStyle='#795443';ctx.beginPath();ctx.arc(xx,yy-12*z,4.5*z,Math.PI,Math.PI*2);ctx.fill();ctx.strokeStyle='#7d8c83';ctx.lineWidth=2*z;ctx.beginPath();ctx.moveTo(xx-5*z,yy-4*z);ctx.lineTo(xx-10*z,yy+3*z);ctx.stroke();
    }else if(kind==='rocky'){
      ctx.fillStyle='#8c9690';ctx.beginPath();ctx.arc(xx,yy-8*z,6*z,0,Math.PI*2);ctx.fill();ctx.fillStyle='#59635f';ctx.beginPath();ctx.moveTo(xx-8*z,yy-1*z);ctx.lineTo(xx,yy-7*z);ctx.lineTo(xx+8*z,yy-1*z);ctx.lineTo(xx+9*z,yy+9*z);ctx.lineTo(xx-9*z,yy+9*z);ctx.closePath();ctx.fill();ctx.fillStyle='#1b211f';ctx.fillRect(xx-4*z,yy-9*z,2*z,2*z);ctx.fillRect(xx+3*z,yy-9*z,2*z,2*z);
    }
  }
  function drawHound(x,y,hp,maxHp){const p=point(x,y,canvas.clientWidth,canvas.clientHeight),z=clamp(p.s/9,.7,1.5),xx=p.x,yy=p.y;if(xx<-45||xx>canvas.clientWidth+45||yy<-40||yy>canvas.clientHeight+20)return;
    ctx.fillStyle='#10131099';ctx.beginPath();ctx.ellipse(xx,yy+3*z,16*z,5*z,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#342c29';ctx.beginPath();ctx.ellipse(xx,yy-4*z,12*z,7*z,-.1,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(xx+5*z,yy-8*z);ctx.lineTo(xx+14*z,yy-12*z);ctx.lineTo(xx+12*z,yy-3*z);ctx.closePath();ctx.fill();ctx.fillStyle='#171718';ctx.beginPath();ctx.moveTo(xx+7*z,yy-8*z);ctx.lineTo(xx+7*z,yy-15*z);ctx.lineTo(xx+11*z,yy-9*z);ctx.fill();ctx.fillStyle='#db5361';ctx.shadowColor='#e43a52';ctx.shadowBlur=7;ctx.fillRect(xx+12*z,yy-8*z,2*z,2*z);ctx.shadowBlur=0;ctx.strokeStyle='#8b4549';ctx.lineWidth=1.5*z;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(xx+i*6*z,yy+1*z);ctx.lineTo(xx+i*7*z,yy+7*z);ctx.stroke()}
  }
  function drawRift(){const p=point(game.rift.x,game.rift.y,canvas.clientWidth,canvas.clientHeight),z=clamp(p.s/9,.75,1.5);if(p.x<-80||p.x>canvas.clientWidth+80||p.y<-120||p.y>canvas.clientHeight+80)return;const {x,y}=p;
    ctx.save();ctx.translate(x,y-28*z);ctx.scale(z,z);ctx.fillStyle='#0a111266';ctx.beginPath();ctx.ellipse(0,34,32,8,0,0,Math.PI*2);ctx.fill();ctx.shadowColor='#70d2bc';ctx.shadowBlur=20;ctx.strokeStyle='#78c9b6';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,15,28,.15,0,Math.PI*2);ctx.stroke();ctx.shadowColor='#c4a4e8';ctx.shadowBlur=14;ctx.strokeStyle='#b798d3';ctx.beginPath();ctx.ellipse(0,0,10,23,-.27,0,Math.PI*2);ctx.stroke();const g=ctx.createRadialGradient(0,0,2,0,0,14);g.addColorStop(0,'#e3f5d6');g.addColorStop(.2,'#83dec0');g.addColorStop(.7,'#28645e');g.addColorStop(1,'#162a2c00');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(0,0,12,24,0,0,Math.PI*2);ctx.fill();ctx.restore();
  }
  function draw(){if(!ctx||!canvas.clientWidth)return;const w=canvas.clientWidth,h=canvas.clientHeight;ctx.clearRect(0,0,w,h);ground(w,h);
    const visible=mapProps.filter(o=>Math.abs(o.x-game.player.x)<48&&Math.abs(o.y-game.player.y)<47).sort((a,b)=>a.y-b.y);
    // landmarks and actors interleaved by depth
    const all=visible.map(o=>({y:o.y,draw:()=>o.type==='tree'?tree(o.x,o.y,o.size,o.variant):rock(o.x,o.y,o.size)}));
    if(game.scene==='wilds'){all.push({y:game.rift.y,draw:drawRift},{y:game.maria.y,draw:()=>drawPerson(game.maria.x,game.maria.y,'maria')},{y:game.rocky.y,draw:()=>drawPerson(game.rocky.x,game.rocky.y,'rocky')});if(game.hound.alive)all.push({y:game.hound.y,draw:()=>drawHound(game.hound.x,game.hound.y,game.hound.hp,game.hound.maxHp)})}
    for(const e of game.enemies.filter(e=>e.alive))all.push({y:e.y,draw:()=>drawHound(e.x,e.y,e.hp,e.maxHp)});
    all.push({y:game.player.y,draw:()=>drawPerson(game.player.x,game.player.y,'player')});all.sort((a,b)=>a.y-b.y);all.forEach(a=>a.draw());
    // atmospheric ash flecks
    for(let i=0;i<32;i++){const x=(i*91+game.time*5)%w,y=(i*67+game.time*12)%h;ctx.fillStyle=`rgba(222,211,183,${.1+((i%3)*.035)})`;ctx.fillRect(x,y,1,1)}
    if(game.scene==='astral')drawAstralOverlay(w,h);
    drawMap();updateWorldUI();
  }
  function drawAstralOverlay(w,h){const g=ctx.createRadialGradient(w*.52,h*.48,5,w*.52,h*.48,w*.65);g.addColorStop(0,'#346b6977');g.addColorStop(.45,'#192d3e66');g.addColorStop(1,'#11101f66');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.save();ctx.globalAlpha=.35;for(let i=0;i<20;i++){const x=(i*97+game.time*9)%w,y=(i*61+game.time*5)%h;ctx.fillStyle=i%2?'#99d6cf':'#be9fd5';ctx.fillRect(x,y,2,2)}ctx.restore()}
  function drawMap(){const w=mapCanvas.width,h=mapCanvas.height;mapCtx.clearRect(0,0,w,h);mapCtx.fillStyle='#1a2423';mapCtx.fillRect(0,0,w,h);mapCtx.strokeStyle='#625e4b';mapCtx.lineWidth=8;mapCtx.beginPath();mapCtx.moveTo(w*.7,h*1.1);mapCtx.quadraticCurveTo(w*.3,h*.55,w*.68,h*-.1);mapCtx.stroke();mapCtx.fillStyle='#2d4036';for(let i=0;i<18;i++){const x=(i*37+9)%w,y=(i*53+13)%h;mapCtx.beginPath();mapCtx.arc(x,y,4+(i%3),0,Math.PI*2);mapCtx.fill()}const px=(game.player.x/100)*w,py=(game.player.y/100)*h;mapCtx.fillStyle='#e3cb87';mapCtx.shadowColor='#d7bd75';mapCtx.shadowBlur=8;mapCtx.beginPath();mapCtx.arc(px,py,4,0,Math.PI*2);mapCtx.fill();mapCtx.shadowBlur=0;if(game.scene==='wilds'){mapCtx.fillStyle='#75cdb6';mapCtx.beginPath();mapCtx.arc(game.rift.x/100*w,game.rift.y/100*h,3,0,Math.PI*2);mapCtx.fill()}}
  function updateWorldUI(){const riftDist=Math.round(Math.hypot(game.rift.x-game.player.x,game.rift.y-game.player.y)*12);$('#riftDistance').textContent=game.quest.riftDone?'STABILIZED':`~${riftDist}m`;$('#coordX').textContent=String(Math.round(game.player.x)).padStart(2,'0');$('#coordY').textContent=String(Math.round(game.player.y)).padStart(2,'0');$('#healthFill').style.width=`${game.player.hp/game.player.maxHp*100}%`;$('#healthText').textContent=`${Math.ceil(game.player.hp)} / ${game.player.maxHp}`;$('#manaFill').style.width=`${game.player.mana/game.player.maxMana*100}%`;$('#manaText').textContent=`${Math.ceil(game.player.mana)} / ${game.player.maxMana}`;$('#xpFill').style.width=`${(game.player.xp%3200)/3200*100}%`;$('#xpLabel').textContent=`${game.player.xp.toLocaleString()} / ${Math.ceil(game.player.xp/3200)*3200}`;
    const near=nearestTarget();const hint=$('#interactHint');if(near&&game.started){hint.classList.add('visible');hint.querySelector('span').textContent=near.label.toUpperCase()}else hint.classList.remove('visible');
    if(game.hound.alive&&game.hound.aggro&&distance(game.player,game.hound)<19){$('#enemyHud').classList.remove('hidden');$('#enemyHealth').style.width=`${game.hound.hp/game.hound.maxHp*100}%`}else if(game.enemies.some(e=>e.alive&&distance(game.player,e)<20)){const e=game.enemies.find(e=>e.alive&&distance(game.player,e)<20);$('#enemyHud').classList.remove('hidden');$('#enemyHealth').style.width=`${e.hp/e.maxHp*100}%`;$('.enemy-name').innerHTML=`ASTRAL WRAITH <span>LV. 9</span>`}else $('#enemyHud').classList.add('hidden');
    $('#zoneName').textContent=game.scene==='astral'?'THE ASTRAL': 'GREENSTONE WILDS';$('#locationTitle').textContent=game.scene==='astral'?'THE VEIL BETWEEN':'THE SUNDERED TRAIL';$('#locationSub').textContent=game.scene==='astral'?'ASTRAL RIFT • REALITY FRACTURE':'GREENSTONE OUTSKIRTS • 18:42';$('#weather').textContent=game.scene==='astral'?'ASTRAL PLANE • UNSTABLE':'ASHFALL • DUSK';
  }
  function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
  function nearestTarget(){if(game.scene==='wilds'){const list=[{x:game.rift.x,y:game.rift.y,label:game.quest.riftDone?'Leave the astral rift':'Enter the astral rift',kind:'rift'},{x:game.maria.x,y:game.maria.y,label:'Speak with Maria',kind:'maria'},{x:game.rocky.x,y:game.rocky.y,label:'Speak with Rocky',kind:'rocky'}];return list.filter(t=>distance(game.player,t)<9).sort((a,b)=>distance(game.player,a)-distance(game.player,b))[0]||null}return distance(game.player,{x:50,y:50})<9?{label:'Escape the astral',kind:'exit'}:null}
  function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(game.toastTimer);game.toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
  function interact(){if(!game.started){startGame();return}const target=nearestTarget();if(!target){toast('Nothing close enough to interact with.');return}if(target.kind==='maria'){openChat('Maria');return}if(target.kind==='rocky'){openChat('Rocky');return}if(target.kind==='rift'){if(game.scene==='wilds'){game.scene='astral';game.player.x=50;game.player.y=52;game.player.hp=Math.max(game.player.hp,game.player.maxHp*.65);game.enemies=[{x:59,y:43,hp:85,maxHp:85,alive:true},{x:40,y:57,hp:110,maxHp:110,alive:true}];if(!game.quest.riftFound){game.quest.riftFound=true;$('#objective').classList.add('complete');$('#questDescription').textContent='Enter the rift and claim its essence.';toast('ASTRAL RIFT LOCATED • Quest updated')}else toast('You step through the shimmering veil.');$('#ambientText').textContent='Reality folds around you.'}else{toast('The rift pulls at your essence…');}draw();return}if(target.kind==='exit'){if(game.enemies.some(e=>e.alive)){toast('The rift is sealed while astral creatures remain.');return}game.scene='wilds';game.player.x=game.rift.x-5;game.player.y=game.rift.y+4;if(!game.quest.essence){game.quest.essence=true;game.player.xp+=480;game.player.gold+=180;game.player.mana=game.player.maxMana;$('#objective2').classList.add('complete');$('#questDescription').textContent='The rift has been closed. Maria will want to hear this.';$('#goldCount').textContent=game.player.gold.toLocaleString();addLoot('Veil-Touched Essence','ESSENCE • RARE','essence');toast('QUEST COMPLETE • Veil-Touched Essence acquired!')}else toast('You return to Greenstone.');draw()}}
  function startGame(){game.started=true;$('#sceneTitleCard').classList.add('dismissed');toast('Journey resumed • Find the astral rift to the northeast');setTimeout(()=>{game.hound.aggro=true;toast('A Rift-touched hound has caught your scent!')},5000);draw()}
  function move(dx,dy,dt){if(!game.started)return;const len=Math.hypot(dx,dy)||1;const speed=dt*.018;game.player.x=clamp(game.player.x+dx/len*speed,3,97);game.player.y=clamp(game.player.y+dy/len*speed,4,96);if(dx)game.player.dir=Math.sign(dx);if(dx||dy){game.player.walk=1;setTimeout(()=>game.player.walk=0,120)}}
  function attack(skill=0){if(!game.started)return;if(game.cooldowns[skill]>0){toast('That ability is not ready yet.');return}const cost=skill===1?22:skill===2?35:0;if(game.player.mana<cost){toast('Not enough mana.');return}game.player.mana-=cost;game.cooldowns[skill]=skill===0?0.38:skill===1?4:6;game.player.attack=.25;$('#combatFlash').classList.remove('hit');void $('#combatFlash').offsetWidth;$('#combatFlash').classList.add('hit');let target=null;
    if(game.scene==='wilds'&&game.hound.alive&&distance(game.player,game.hound)<18)target=game.hound;
    if(!target)target=game.enemies.find(e=>e.alive&&distance(game.player,e)<19);
    if(target){const dmg=skill===0?28:skill===1?48:skill===2?72:38;target.hp-=dmg;toast(`${skill===2?'BLOOD BOLT':skill===1?'SHADOW STEP':'VEIL STRIKE'} • ${dmg} damage`);if(target.hp<=0){target.hp=0;target.alive=false;game.player.xp+=skill===2?220:160;game.player.gold+=Math.round(rand(20,50));$('#goldCount').textContent=game.player.gold.toLocaleString();addLoot(Math.random()<.35?'Rift-scorched Fang':'Astral Shard',Math.random()<.35?'UNCOMMON • MATERIAL':'COMMON • CRAFTING','common');if(game.scene==='astral'&&!game.enemies.some(e=>e.alive)){toast('The astral creatures are defeated. Return to the rift.');game.player.mana=Math.min(game.player.maxMana,game.player.mana+30)}else if(game.scene==='wilds')toast('Rift-touched hound defeated • loot collected')}}else{toast(skill===1?'You shadow-step forward.':skill===2?'Blood energy gathers in your palm.':'Your blade cuts through the air.')}draw();}
  function addLoot(name,desc,type){game.loot.unshift({name,desc,type});if(game.loot.length>5)game.loot.pop();const list=$('#lootList');list.innerHTML=game.loot.map((l,i)=>`<div class="loot-row"><span class="loot-emblem ${l.type}">${l.type==='essence'?'✹':'◈'}</span><div><b>${l.name}</b><small>${l.desc}</small></div><span class="loot-time">now</span></div>`).join('')}
