function testLog(text,cls=''){const out=$('#testConsoleOutput');if(!out)return;const line=document.createElement('div');if(cls)line.className=cls;line.textContent=text;out.appendChild(line);out.scrollTop=out.scrollHeight}
function toggleTestConsole(force){const panel=$('#testConsole');if(!panel)return;const show=typeof force==='boolean'?force:panel.classList.contains('hidden');panel.classList.toggle('hidden',!show);if(show)$('#testConsoleInput').focus()}
function runTestCommand(raw){const parts=raw.trim().match(/(?:[^\s"]+|"[^"]*")+/g)||[];const args=parts.map(v=>v.replace(/^"|"$/g,''));const cmd=(args.shift()||'').toLowerCase();testLog(`> ${raw}`,'cmd');
  if(cmd==='help'){testLog('Commands:\nhelp — list commands\ngo rift|greenstone|astral — teleport\ntp X Y — teleport to coordinates\ngive essence NAME — add/equip an essence\ngive item NAME — add inventory loot\ngive gold AMOUNT\ngive xp AMOUNT\ngive potion AMOUNT\nset hp AMOUNT|set mana AMOUNT|set rank NAME|set level AMOUNT\nkill hound|kill astral|heal|quest essences|unlock all|clear\nSecret essence names: Peanut Butter, Jam, Bread, Sandwich','success')}
  else if(cmd==='clear'){$('#testConsoleOutput').innerHTML=''}
  else if(cmd==='go'||cmd==='tp'){const place=(args[0]||'').toLower; if(cmd==='go'){if(place==='rift'||place==='astral'){game.scene='astral';game.player.x=50;game.player.y=52;game.enemies=[{x:59,y:43,hp:85,maxHp:85,alive:true},{x:40,y:57,hp:110,maxHp:110,alive:true}]}else if(place==='greenstone'){game.scene='wilds';game.player.x=22;game.player.y=63}else{testLog('Unknown location. Use: go rift, go astral, or go greenstone','error');return}testLog(`Teleported to ${place==='astral'?'Astral Kingdom':place==='rift'?'Astral Rift':place==='greenstone'?'Greenstone':'requested location'}`,'success')}else{const x=Number(args[0]),y=Number(args[1]);if(!Number.isFinite(x)||!Number.isFinite(y)){testLog('Usage: tp X Y','error');return}game.player.x=clamp(x,3,97);game.player.y=clamp(y,4,96);testLog(`Teleported to ${game.player.x}, ${game.player.y}`,'success')}draw()}
  else if(cmd==='give'){const kind=(args.shift()||'').toLowerCase();const name=args.join(' ').trim();if(kind==='essence'){equipTestEssence(name)}else if(kind==='item'){if(!name){testLog('Usage: give item NAME','error');return}addLoot(name,'TEST ITEM • PREVIEW','common');testLog(`Added ${name}`,'success')}else if(kind==='gold'){const n=Number(name)||0;game.player.gold+=n;$('#goldCount').textContent=game.player.gold.toLocaleString();testLog(`Gold +${n}`,'success')}else if(kind==='xp'){const n=Number(name)||0;game.player.xp+=n;testLog(`XP +${n}`,'success')}else if(kind==='potion'){const n=Number(name)||1;game.player.potions+=n;$('.potion b').textContent=game.player.potions;testLog(`Potions +${n}`,'success')}else testLog('Usage: give essence NAME | item NAME | gold N | xp N | potion N','error')}
  else if(cmd==='set'){const kind=(args.shift()||'').toLowerCase();const val=args.join(' ').trim();if(kind==='hp'){game.player.hp=clamp(Number(val)||game.player.maxHp,0,game.player.maxHp);testLog(`HP set to ${game.player.hp}`,'success')}else if(kind==='mana'){game.player.mana=clamp(Number(val)||game.player.maxMana,0,game.player.maxMana);testLog(`Mana set to ${game.player.mana}`,'success')}else if(kind==='rank'){document.querySelector('.hero-class').innerHTML=`OUTWORLDER <span>•</span> ${val.toUpper ? val.toUpper() : String(val).toUpperCase()}`;testLog(`Rank set to ${val}`,'success')}else if(kind==='level'){game.player.level=Number(val)||game.player.level;const dot=document.querySelector('.rank-dot');if(dot)dot.textContent=game.player.level;testLog(`Level set to ${game.player.level}`,'success')}else testLog('Usage: set hp N | mana N | rank NAME | level N','error')}
  else if(cmd==='heal'){game.player.hp=game.player.maxHp;game.player.mana=game.player.maxMana;testLog('Vitals restored','success')}
  else if(cmd==='kill'&&args[0]){if(args[0].toLowerCase()==='hound'){game.hound.alive=false;game.hound.hp=0}else if(args[0].toLowerCase()==='astral'){game.enemies.forEach(e=>{e.alive=false;e.hp=0})}testLog(`${args[0]} defeated (test)`, 'success');draw()}
  else if(cmd==='quest'&&args[0]==='essences'){game.quest.riftFound=true;game.quest.essence=true;game.quest.riftDone=true;Object.assign(game.essences,{shadow:true,blood:true,veil:true});testLog('Rift essence quest marked complete','success')}
  else if(cmd==='unlock'&&args[0]==='all'){['peanut butter','jam','bread','sandwich'].forEach(name=>equipTestEssence(name));testLog('All preview essences unlocked','success')}
  else testLog('Unknown command. Type help.','error')}
function equipTestEssence(name){const key=name.toLowerCase().trim();const canonical=key.includes('peanut')?'Peanut Butter':key==='jam'?'Jam':key==='bread'?'Bread':key==='sandwich'?'Sandwich':name||'Unknown Essence';let slotIndex=0;for(let i=1;i<=3;i++){const slot=document.querySelector(`[data-essence="slot${i}"]`)||document.querySelector(i===3?'#emptySlot':'.none');if(slot&&!slot.classList.contains('equipped')){slotIndex=i;break}}const slot=document.querySelector(`[data-essence="slot${slotIndex}"]`)||document.querySelector('#emptySlot');if(slot){slot.classList.remove('empty');slot.classList.add('equipped');slot.dataset.essence=key;slot.innerHTML=`<span class="essence-symbol">✦</span><span><b>${canonical.toUpperCase()}</b><small>TEST ESSENCE • OVERPOWERED</small></span><i>0${slotIndex}</i>`}game.essences[key]=true;addLoot(`${canonical} Essence`,'ESSENCE • TEST MODE • EQUIPPED','essence');testLog(`${canonical} Essence acquired and equipped`,'success')}
function handleKey(e){const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key)&&e.target===document.body)e.preventDefault();if(e.key==='~'||e.key==='`'){e.preventDefault();toggleTestConsole();return}if(e.target&&(['INPUT','TEXTAREA'].includes(e.target.tagName)))return;if(key==='e')interact();else if(key===' '||key==='j')attack(0);else if(key==='1')attack(1);else if(key==='2')attack(2);else if(key==='3')attack(0);else if(key==='q')usePotion();else game.keys[key]=true}

